BEGIN;
-- Frozen descriptors from research-intake-core 1.0.0; no client descriptors accepted.
CREATE FUNCTION research_private.intake_contract() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $f$ SELECT $json${"operations":{"intakePublicInfo":{"request":{},"result":{"terms":"IntakeTerms|null","acceptingApplications":"boolean"},"authority":"public; published terms only"},"intakeSubmit":{"request":{"requestId":"uuid","termsVersionId":"uuid","termsHash":"sha256","acknowledged":"true","application":"PublicApplicationData"},"result":{"receipt":"IntakeReceipt {id,status:submitted,submittedAt}"},"authority":"public proposal only; no identity or grants"},"intakeOwnerBootstrap":{"request":{},"result":{"termsState":"IntakeTermsState {revision,draftVersion,publishedVersionId}","identities":"IndividualIdentity[]","institutions":"string[]"},"authority":"owner"},"intakeList":{"request":{"status":"IntakeStatus?","query":"string?","cursor":"string?"},"result":{"applications":"IntakeApplicationSummary[]","nextCursor":"string|null"},"authority":"owner"},"intakeGet":{"request":{"applicationId":"uuid"},"result":{"application":"IntakeApplication","terms":"IntakeTerms","workspace":"WorkspaceSummary?"},"authority":"owner"},"intakeTermsSave":{"request":{"requestId":"uuid","expectedRevision":"integer","title":"string","text":"string"},"result":{"termsState":"IntakeTermsState"},"authority":"owner; proposed draft only"},"intakeTermsPublish":{"request":{"requestId":"uuid","expectedRevision":"integer","versionId":"uuid"},"result":{"termsState":"IntakeTermsState"},"authority":"owner; explicit exact-version publication"},"intakeReview":{"request":{"requestId":"uuid","applicationId":"uuid","expectedRevision":"integer","decision":"under_review|rejected|approved","note":"string?","studyId":"uuid? approval only","studyExpectedRevision":"integer? approval only","individualCode":"string? approval only","permissions":"string[]? approval only; explicit view_study"},"result":{"application":"IntakeApplication","partner":"Partner?","workspace":"WorkspaceSummary?"},"authority":"owner; approval binds selected live identity and explicit study grants"},"intakeIdentityCreate":{"request":{"requestId":"uuid","institution":"string","label":"string"},"result":{"identity":"IndividualIdentity"},"authority":"owner; existing access mechanism; no automatic tool or research grants"}},"publicFields":[{"id":"title","label":"כותרת","type":"text","required":true,"maxLength":240},{"id":"applicationType","label":"סוג הבקשה","type":"enum","choices":{"partnership":"שותפות","study":"מחקר","access":"גישה"},"required":true},{"id":"fullName","label":"שם מלא","type":"text","required":true},{"id":"email","label":"דוא״ל","type":"email","required":true},{"id":"applicantType","label":"סוג הפונה","type":"enum","choices":{"individual":"אדם פרטי","institution":"מוסד"}},{"id":"institution","label":"מוסד","type":"text","required":true,"requiredUnless":{"field":"applicantType","equals":"individual"}},{"id":"department","label":"מחלקה","type":"text"},{"id":"position","label":"תפקיד","type":"text"},{"id":"phone","label":"טלפון","type":"text"},{"id":"profileNotes","label":"פרטים מקצועיים","type":"text"},{"id":"researchInterests","label":"תחומי מחקר","type":"tags"},{"id":"background","label":"רקע","type":"text"},{"id":"objectives","label":"מטרות","type":"text","required":true},{"id":"researchQuestions","label":"שאלות מחקר","type":"tags","required":true},{"id":"method","label":"שיטת המחקר","type":"text","required":true},{"id":"population","label":"אוכלוסיית המחקר","type":"text","required":true},{"id":"requestedTools","label":"כלים מבוקשים","type":"tags","required":true},{"id":"startDate","label":"מועד התחלה","type":"date","required":true},{"id":"endDate","label":"מועד סיום","type":"date","required":true},{"id":"ethicsStatus","label":"מצב אישור אתי","type":"enum","choices":{"pending":"בתהליך","approved":"אושר","not_required":"לא נדרש לפי תיעוד"},"required":true},{"id":"ethicsDetails","label":"פירוט אישורים","type":"text","required":true},{"id":"consentPlan","label":"תוכנית הסכמה","type":"text","required":true},{"id":"requestedPermissions","label":"הרשאות מבוקשות","type":"tags","choices":["view_study","edit_study","manage_questionnaires","view_aggregate_results","view_pseudonymized_data","view_identifiable_data","view_document_content","export_data","manage_participants","contact_participants","manage_researchers","manage_consent","view_audit_log","view_approved_findings","download_approved_findings","propose_analysis","view_analysis_results","comment_on_findings","view_approved_pseudonymized_data","export_approved_dataset","view_study_progress","view_approved_contributions"],"category":"access","required":true},{"id":"requestedSupport","label":"סיוע מבוקש","type":"text"}],"requiredFields":["title","applicationType","fullName","email","objectives","requestedTools","applicantType"],"defaultDraft":{"title":"טיוטת תנאי פנייה לשותפות","text":"זהו נוסח מוצע לעיון בעלת המערכת לפני פרסום. הפנייה היא בקשה לבדיקה. הגשתה אינה יוצרת חשבון, הרשאה, שותפות פעילה או התחייבות. אישור הקריאה אינו חתימה על הסכם."}}$json$::jsonb $f$;

CREATE TABLE research_private.intake_terms_versions(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),number integer NOT NULL UNIQUE,title text NOT NULL,text text NOT NULL,hash text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE research_private.intake_terms_state(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),revision integer NOT NULL DEFAULT 0,draft_version_id uuid NOT NULL REFERENCES research_private.intake_terms_versions(id),published_version_id uuid REFERENCES research_private.intake_terms_versions(id));
CREATE TABLE research_private.intake_terms_publications(version_id uuid PRIMARY KEY REFERENCES research_private.intake_terms_versions(id),published_by text NOT NULL,published_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE research_private.intake_applications(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),request_id uuid NOT NULL UNIQUE,payload_hash text NOT NULL,application jsonb NOT NULL,terms_version_id uuid NOT NULL REFERENCES research_private.intake_terms_versions(id),terms_hash text NOT NULL,acknowledged_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,submitted_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE research_private.intake_decisions(application_id uuid PRIMARY KEY REFERENCES research_private.intake_applications(id),revision integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','under_review','approved','rejected')),partner_id uuid REFERENCES research_private.partnership_partners(id),study_id uuid REFERENCES research_private.studies(id),record_id uuid REFERENCES research_private.partnership_records(id),reviewed_at timestamptz);
CREATE TABLE research_private.intake_reviews(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),application_id uuid NOT NULL REFERENCES research_private.intake_applications(id),revision integer NOT NULL,decision text NOT NULL,note text NOT NULL,reviewed_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(application_id,revision));
CREATE TABLE research_private.intake_receipts(actor_ref text NOT NULL,action text NOT NULL,request_id uuid NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(actor_ref,action,request_id));
CREATE TABLE research_private.intake_rate_windows(bucket text NOT NULL CHECK(bucket~'^[a-f0-9]{64}$'),minute timestamptz NOT NULL,count integer NOT NULL,PRIMARY KEY(bucket,minute));
WITH draft AS (SELECT research_private.intake_contract()->'defaultDraft' data),version AS (INSERT INTO research_private.intake_terms_versions(number,title,text,hash,created_by) SELECT 1,data->>'title',data->>'text',research_private.partnership_hash(data),'system-draft' FROM draft RETURNING id) INSERT INTO research_private.intake_terms_state(draft_version_id) SELECT id FROM version;
DO $tables$ DECLARE t text; BEGIN
 FOR t IN SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='research_private' AND tablename LIKE 'intake_%' LOOP
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I OWNER TO research_table_owner',t);
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE pg_catalog.format('REVOKE ALL ON research_private.%I FROM PUBLIC,anon,authenticated,service_role',t);
  EXECUTE pg_catalog.format('GRANT SELECT,INSERT,UPDATE,DELETE ON research_private.%I TO research_worker',t);
  EXECUTE pg_catalog.format('CREATE POLICY intake_owner ON research_private.%I TO research_worker USING(pg_catalog.current_setting(''research.owner'',true)=''true'') WITH CHECK(pg_catalog.current_setting(''research.owner'',true)=''true'')',t);
  IF t IN ('intake_terms_versions','intake_terms_publications','intake_applications','intake_reviews','intake_receipts') THEN EXECUTE pg_catalog.format('CREATE TRIGGER intake_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON research_private.%I FOR EACH STATEMENT EXECUTE FUNCTION research_private.immutable()',t); END IF;
 END LOOP;
END $tables$;
CREATE POLICY intake_public ON research_private.intake_terms_versions FOR SELECT TO research_worker USING(pg_catalog.current_setting('research.intake_public',true)='true');
CREATE POLICY intake_public ON research_private.intake_terms_publications FOR SELECT TO research_worker USING(pg_catalog.current_setting('research.intake_public',true)='true');
CREATE POLICY intake_public ON research_private.intake_terms_state FOR SELECT TO research_worker USING(pg_catalog.current_setting('research.intake_public',true)='true');
CREATE POLICY intake_public ON research_private.intake_applications TO research_worker USING(request_id::text=pg_catalog.current_setting('research.intake_request',true)) WITH CHECK(request_id::text=pg_catalog.current_setting('research.intake_request',true));
CREATE POLICY intake_public ON research_private.intake_decisions FOR INSERT TO research_worker WITH CHECK(application_id::text=pg_catalog.current_setting('research.intake_application',true));
CREATE POLICY intake_public ON research_private.intake_rate_windows TO research_worker USING(bucket=pg_catalog.current_setting('research.intake_bucket',true)) WITH CHECK(bucket=pg_catalog.current_setting('research.intake_bucket',true));

CREATE FUNCTION research_private.intake_terms(v research_private.intake_terms_versions) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('versionId',v.id,'number',v.number,'title',v.title,'text',v.text,'hash',v.hash)||COALESCE((SELECT pg_catalog.jsonb_build_object('publishedAt',p.published_at) FROM research_private.intake_terms_publications p WHERE p.version_id=v.id),'{}') $f$;
CREATE FUNCTION research_private.intake_terms_state_json() RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('revision',s.revision,'draftVersion',research_private.intake_terms(v),'publishedVersionId',s.published_version_id) FROM research_private.intake_terms_state s JOIN research_private.intake_terms_versions v ON v.id=s.draft_version_id $f$;
CREATE FUNCTION research_private.intake_application_json(a research_private.intake_applications,d research_private.intake_decisions) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',a.id,'status',d.status,'revision',d.revision,'application',a.application,'termsVersionId',a.terms_version_id,'termsHash',a.terms_hash,'acknowledgedAt',a.acknowledged_at,'submittedAt',a.submitted_at,'partnerId',d.partner_id,'studyId',d.study_id,'recordId',d.record_id,'reviews',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('decision',r.decision,'note',r.note,'reviewedBy',r.reviewed_by,'createdAt',r.created_at,'revision',r.revision) ORDER BY r.revision) FROM research_private.intake_reviews r WHERE r.application_id=a.id),'[]')) $f$;

CREATE FUNCTION research_private.intake_request(action text,body jsonb) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE fields jsonb; k text; typ text; val jsonb; str text; max_length integer; app jsonb; BEGIN
 fields:=research_private.intake_contract()#>ARRAY['operations',action,'request'];
 IF fields IS NULL OR action='intakeIdentityCreate' OR pg_catalog.jsonb_typeof(body) IS DISTINCT FROM 'object' THEN PERFORM research_private.fail('invalid'); END IF;
 FOR k IN SELECT pg_catalog.jsonb_object_keys(body) LOOP IF NOT(fields ? k) AND NOT(action='intakeSubmit' AND k='rateBucket') THEN PERFORM research_private.fail('invalid'); END IF; END LOOP;
 FOR k,typ IN SELECT key,value#>>'{}' FROM pg_catalog.jsonb_each(fields) LOOP
  val:=body->k;str:=body->>k;
  IF val IS NULL THEN IF pg_catalog.strpos(typ,'?')=0 THEN PERFORM research_private.fail('invalid'); END IF;CONTINUE;END IF;
  IF k='application' THEN
   app:=val;PERFORM research_private.partnership_fields(research_private.intake_contract()->'publicFields',app,NULL,NULL,false);
   FOR str IN SELECT pg_catalog.jsonb_array_elements_text(research_private.intake_contract()->'requiredFields') LOOP IF app->str IS NULL OR app->str='null'::jsonb OR app->str='[]'::jsonb OR pg_catalog.btrim(app->>str)='' THEN PERFORM research_private.fail('invalid');END IF; END LOOP;
   IF app->>'applicantType'='institution' AND pg_catalog.btrim(COALESCE(app->>'institution',''))='' OR COALESCE(app->>'startDate','')<>'' AND COALESCE(app->>'endDate','')<>'' AND app->>'startDate'>app->>'endDate' THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF typ LIKE 'uuid%' THEN IF pg_catalog.jsonb_typeof(val)<>'string' OR str!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF typ LIKE 'integer%' THEN IF pg_catalog.jsonb_typeof(val)<>'number' OR str!~'^[0-9]+$' OR str::numeric>9007199254740991 THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF k='termsHash' THEN IF pg_catalog.jsonb_typeof(val)<>'string' OR str!~*'^[a-f0-9]{64}$' THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF k='acknowledged' THEN IF val IS DISTINCT FROM 'true'::jsonb THEN PERFORM research_private.fail('invalid');END IF;
  ELSIF k='permissions' THEN IF pg_catalog.jsonb_typeof(val)<>'array' THEN PERFORM research_private.fail('invalid');END IF;
   IF NOT(val ? 'view_study') OR pg_catalog.jsonb_array_length(val)>pg_catalog.cardinality(research_private.permissions()) OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(val) x WHERE pg_catalog.jsonb_typeof(x)<>'string' OR NOT((x#>>'{}')=ANY(research_private.permissions()))) OR (SELECT pg_catalog.count(*)<>pg_catalog.count(DISTINCT x) FROM pg_catalog.jsonb_array_elements(val) x) THEN PERFORM research_private.fail('invalid');END IF;
  ELSE
   max_length:=CASE k WHEN 'title' THEN 240 WHEN 'query' THEN 500 WHEN 'cursor' THEN 2000 WHEN 'individualCode' THEN 100 ELSE 20000 END;
   IF pg_catalog.jsonb_typeof(val)<>'string' OR pg_catalog.length(str)>max_length OR k IN ('title','text','institution','label','individualCode') AND pg_catalog.btrim(str)='' OR k='status' AND str NOT IN ('submitted','under_review','approved','rejected') OR k='decision' AND str NOT IN ('under_review','rejected','approved') THEN PERFORM research_private.fail('invalid');END IF;
  END IF;
 END LOOP;
 IF action='intakeReview' THEN IF body->>'decision'='approved' THEN IF NOT(body ?& ARRAY['studyId','studyExpectedRevision','individualCode','permissions']) THEN PERFORM research_private.fail('invalid');END IF;ELSIF body ?| ARRAY['studyId','studyExpectedRevision','individualCode','permissions'] THEN PERFORM research_private.fail('invalid');END IF;END IF;
END $f$;

CREATE FUNCTION research_private.intake_reset() RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$ DECLARE key text; BEGIN
 FOR key IN SELECT pg_catalog.unnest(ARRAY['actor','study','partner','partner_invite','invite','intake_request','intake_application','intake_bucket']) LOOP PERFORM pg_catalog.set_config('research.'||key,'',true);END LOOP;
 FOR key IN SELECT pg_catalog.unnest(ARRAY['owner','internal','signing','erasing','intake_public']) LOOP PERFORM pg_catalog.set_config('research.'||key,'false',true);END LOOP;
 PERFORM pg_catalog.set_config('research.permissions','[]',true);
END $f$;
CREATE FUNCTION research_private.intake_dispatch(p_token text,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
#variable_conflict use_variable
DECLARE auth jsonb;actor text;is_public boolean:=p_action IN ('intakePublicInfo','intakeSubmit');request_id uuid;hash text;receipt research_private.intake_receipts;terms_state research_private.intake_terms_state;terms research_private.intake_terms_versions;a research_private.intake_applications;d research_private.intake_decisions;p research_private.partnership_partners;s research_private.studies;result jsonb;part_result jsonb;member_result jsonb;record_result jsonb;profile jsonb;workspace jsonb;items jsonb;cursor_id uuid;cursor_time timestamptz;next_cursor text;bucket text;rate_total integer; BEGIN
 PERFORM research_private.intake_reset();PERFORM research_private.intake_request(p_action,p_payload);
 IF is_public THEN IF COALESCE(p_token,'')<>'' THEN PERFORM research_private.fail('invalid');END IF;actor:='intake-public';PERFORM pg_catalog.set_config('research.intake_public','true',true);
 ELSE auth:=research_private.auth(p_token);IF auth->>'owner' IS DISTINCT FROM 'true' THEN PERFORM research_private.fail('unauthorized');END IF;actor:=auth->>'actor';PERFORM pg_catalog.set_config('research.owner','true',true);END IF;
 PERFORM pg_catalog.set_config('research.actor',actor,true);
 IF p_payload ? 'requestId' THEN
  request_id:=(p_payload->>'requestId')::uuid;hash:=research_private.partnership_hash(p_payload-'requestId'-'rateBucket');
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor||p_action||request_id,0));
  IF p_action='intakeSubmit' THEN
   PERFORM pg_catalog.set_config('research.intake_request',request_id::text,true);SELECT * INTO a FROM research_private.intake_applications x WHERE x.request_id=request_id;
   IF a.id IS NOT NULL THEN IF a.payload_hash<>hash THEN PERFORM research_private.fail('conflict');END IF;RETURN pg_catalog.jsonb_build_object('receipt',pg_catalog.jsonb_build_object('id',a.id,'status','submitted','submittedAt',a.submitted_at));END IF;
  ELSE SELECT * INTO receipt FROM research_private.intake_receipts x WHERE x.actor_ref=actor AND x.action=p_action AND x.request_id=request_id;
   IF receipt.request_id IS NOT NULL THEN IF receipt.payload_hash<>hash THEN PERFORM research_private.fail('conflict');END IF;RETURN receipt.result;END IF;
  END IF;
 END IF;
 IF p_action='intakePublicInfo' THEN
  SELECT v.* INTO terms FROM research_private.intake_terms_state x JOIN research_private.intake_terms_versions v ON v.id=x.published_version_id;
  result:=pg_catalog.jsonb_build_object('terms',CASE WHEN terms.id IS NULL THEN NULL ELSE research_private.intake_terms(terms) END,'acceptingApplications',terms.id IS NOT NULL);
 ELSIF p_action='intakeSubmit' THEN
  bucket:=p_payload->>'rateBucket';IF pg_catalog.jsonb_typeof(p_payload->'rateBucket') IS DISTINCT FROM 'string' OR bucket!~'^[a-f0-9]{64}$' THEN PERFORM research_private.fail('invalid');END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('research-intake-terms',0));
  SELECT * INTO terms_state FROM research_private.intake_terms_state;SELECT * INTO terms FROM research_private.intake_terms_versions x WHERE x.id=terms_state.published_version_id;
  IF terms.id IS NULL OR terms.id IS DISTINCT FROM (p_payload->>'termsVersionId')::uuid OR terms.hash<>pg_catalog.lower(p_payload->>'termsHash') THEN PERFORM research_private.fail('conflict');END IF;
  PERFORM pg_catalog.set_config('research.intake_bucket',bucket,true);
  INSERT INTO research_private.intake_rate_windows(bucket,minute,count) VALUES(bucket,pg_catalog.date_trunc('minute',CURRENT_TIMESTAMP),1) ON CONFLICT ON CONSTRAINT intake_rate_windows_pkey DO UPDATE SET count=intake_rate_windows.count+1 RETURNING count INTO rate_total;
  IF rate_total>20 THEN PERFORM research_private.fail('rate_limited');END IF;
  INSERT INTO research_private.intake_applications(request_id,payload_hash,application,terms_version_id,terms_hash) VALUES(request_id,hash,p_payload->'application',terms.id,terms.hash) RETURNING * INTO a;
  PERFORM pg_catalog.set_config('research.intake_application',a.id::text,true);INSERT INTO research_private.intake_decisions(application_id) VALUES(a.id);
  result:=pg_catalog.jsonb_build_object('receipt',pg_catalog.jsonb_build_object('id',a.id,'status','submitted','submittedAt',a.submitted_at));
 ELSIF p_action='intakeOwnerBootstrap' THEN result:=pg_catalog.jsonb_build_object('termsState',research_private.intake_terms_state_json(),'identities','[]'::jsonb,'institutions','[]'::jsonb);
 ELSIF p_action IN ('intakeTermsSave','intakeTermsPublish') THEN
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('research-intake-terms',0));SELECT * INTO terms_state FROM research_private.intake_terms_state FOR UPDATE;
  IF terms_state.revision<>(p_payload->>'expectedRevision')::integer THEN PERFORM research_private.fail('conflict');END IF;
  IF p_action='intakeTermsSave' THEN
   INSERT INTO research_private.intake_terms_versions(number,title,text,hash,created_by) SELECT COALESCE(pg_catalog.max(number),0)+1,p_payload->>'title',p_payload->>'text',research_private.partnership_hash(pg_catalog.jsonb_build_object('title',p_payload->>'title','text',p_payload->>'text')),actor FROM research_private.intake_terms_versions RETURNING * INTO terms;
   UPDATE research_private.intake_terms_state SET draft_version_id=terms.id,revision=revision+1;
  ELSE
   IF terms_state.draft_version_id IS DISTINCT FROM (p_payload->>'versionId')::uuid OR terms_state.published_version_id IS NOT DISTINCT FROM (p_payload->>'versionId')::uuid THEN PERFORM research_private.fail('conflict');END IF;
   INSERT INTO research_private.intake_terms_publications(version_id,published_by) VALUES(terms_state.draft_version_id,actor);
   UPDATE research_private.intake_terms_state SET published_version_id=terms_state.draft_version_id,revision=revision+1;
  END IF;result:=pg_catalog.jsonb_build_object('termsState',research_private.intake_terms_state_json());
 ELSIF p_action='intakeList' THEN
  IF p_payload ? 'cursor' THEN
   IF p_payload->>'cursor'!~'^[0-9T:.+ Z-]+\|[a-f0-9-]{36}$' THEN PERFORM research_private.fail('invalid');END IF;
   cursor_time:=pg_catalog.split_part(p_payload->>'cursor','|',1)::timestamptz;cursor_id:=pg_catalog.split_part(p_payload->>'cursor','|',2)::uuid;
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(row.data ORDER BY row.submitted_at DESC,row.id DESC),'[]') INTO items FROM (SELECT ia.id,ia.submitted_at,pg_catalog.jsonb_build_object('id',ia.id,'status',idc.status,'revision',idc.revision,'title',ia.application->>'title','fullName',ia.application->>'fullName','institution',ia.application->>'institution','applicantType',ia.application->>'applicantType','submittedAt',ia.submitted_at) data FROM research_private.intake_applications ia JOIN research_private.intake_decisions idc ON idc.application_id=ia.id WHERE (NOT(p_payload ? 'status') OR idc.status=p_payload->>'status') AND (NOT(p_payload ? 'query') OR pg_catalog.strpos(pg_catalog.lower((ia.application->>'title')||' '||(ia.application->>'fullName')||' '||COALESCE(ia.application->>'institution','')||' '||(ia.application->>'email')),pg_catalog.lower(p_payload->>'query'))>0) AND (cursor_id IS NULL OR (ia.submitted_at,ia.id)<(cursor_time,cursor_id)) ORDER BY ia.submitted_at DESC,ia.id DESC LIMIT 51) row;
  next_cursor:=NULL;IF pg_catalog.jsonb_array_length(items)>50 THEN next_cursor:=(items->49->>'submittedAt')||'|'||(items->49->>'id');items:=items-50;END IF;
  result:=pg_catalog.jsonb_build_object('applications',items,'nextCursor',next_cursor);
 ELSIF p_action IN ('intakeGet','intakeReview') THEN
  SELECT * INTO a FROM research_private.intake_applications x WHERE x.id=(p_payload->>'applicationId')::uuid;IF a.id IS NULL THEN PERFORM research_private.fail('not_found');END IF;
  SELECT * INTO d FROM research_private.intake_decisions x WHERE x.application_id=a.id FOR UPDATE;
  IF p_action='intakeReview' THEN
    IF d.revision<>(p_payload->>'expectedRevision')::integer OR d.status NOT IN ('submitted','under_review') THEN PERFORM research_private.fail('conflict');END IF;
   IF p_payload->>'decision'='approved' THEN
    IF p_payload->>'individualCode'!~'^[A-Z0-9]+$' THEN PERFORM research_private.fail('invalid');END IF;PERFORM research_private.live_individual(p_payload->>'individualCode');
    member_result:=research_private.dispatch(p_token,'memberSet',pg_catalog.jsonb_build_object('requestId',pg_catalog.gen_random_uuid(),'studyId',p_payload->>'studyId','expectedRevision',p_payload->'studyExpectedRevision','code',p_payload->>'individualCode','role','researcher','permissions',p_payload->'permissions','delegablePermissions','[]'::jsonb));IF member_result ? 'error' THEN PERFORM research_private.fail(member_result->>'error');END IF;
    SELECT * INTO p FROM research_private.partnership_partners x WHERE x.actor_ref='code:'||(p_payload->>'individualCode') FOR UPDATE;
    IF p.id IS NULL THEN
     SELECT COALESCE(pg_catalog.jsonb_object_agg(x.key,x.value),'{}') INTO profile FROM pg_catalog.jsonb_each(a.application) x WHERE EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(research_private.partnership_contract()->'partner') f WHERE f->>'id'=x.key);
     part_result:=research_private.partnership_dispatch(p_token,'partnerSave',pg_catalog.jsonb_build_object('requestId',pg_catalog.gen_random_uuid(),'individualCode',p_payload->>'individualCode','expectedRevision',NULL,'profile',profile));IF part_result ? 'error' THEN PERFORM research_private.fail(part_result->>'error');END IF;
     SELECT * INTO p FROM research_private.partnership_partners x WHERE x.id=(part_result#>>'{partner,id}')::uuid;
    END IF;
    record_result:=research_private.partnership_dispatch(p_token,'recordSave',pg_catalog.jsonb_build_object('requestId',pg_catalog.gen_random_uuid(),'studyId',p_payload->>'studyId','partnerId',p.id,'expectedRevision',NULL,'kind','application','data',a.application));IF record_result ? 'error' THEN PERFORM research_private.fail(record_result->>'error');END IF;
    UPDATE research_private.intake_decisions SET partner_id=p.id,study_id=(p_payload->>'studyId')::uuid,record_id=(record_result#>>'{record,id}')::uuid WHERE application_id=a.id;
   END IF;
   UPDATE research_private.intake_decisions SET revision=revision+1,status=p_payload->>'decision',reviewed_at=CURRENT_TIMESTAMP WHERE application_id=a.id RETURNING * INTO d;
   INSERT INTO research_private.intake_reviews(application_id,revision,decision,note,reviewed_by) VALUES(a.id,d.revision,d.status,COALESCE(p_payload->>'note',''),actor);
  END IF;
  workspace:=NULL;IF d.partner_id IS NOT NULL THEN SELECT * INTO p FROM research_private.partnership_partners x WHERE x.id=d.partner_id;SELECT * INTO s FROM research_private.studies x WHERE x.id=d.study_id;workspace:=research_private.partnership_workspace(s,p);END IF;
  result:=pg_catalog.jsonb_build_object('application',research_private.intake_application_json(a,d));
  IF p_action='intakeGet' THEN SELECT * INTO terms FROM research_private.intake_terms_versions x WHERE x.id=a.terms_version_id;result:=result||pg_catalog.jsonb_build_object('terms',research_private.intake_terms(terms),'workspace',workspace);
  ELSE result:=result||pg_catalog.jsonb_build_object('partner',CASE WHEN p.id IS NULL THEN NULL ELSE research_private.partnership_partner(p) END,'workspace',workspace);END IF;
 ELSE PERFORM research_private.fail('invalid');END IF;
 IF NOT is_public AND request_id IS NOT NULL THEN INSERT INTO research_private.intake_receipts(actor_ref,action,request_id,payload_hash,result) VALUES(actor,p_action,request_id,hash,result);END IF;
 RETURN result;
EXCEPTION WHEN SQLSTATE 'P0001' THEN RETURN pg_catalog.jsonb_build_object('error',SQLERRM,'status',CASE SQLERRM WHEN 'unauthorized' THEN 403 WHEN 'not_found' THEN 404 WHEN 'conflict' THEN 409 WHEN 'rate_limited' THEN 429 ELSE 400 END);
 WHEN invalid_text_representation OR invalid_parameter_value OR check_violation OR not_null_violation OR foreign_key_violation OR datetime_field_overflow OR invalid_datetime_format OR numeric_value_out_of_range THEN RETURN '{"error":"invalid","status":400}'::jsonb;
 WHEN unique_violation THEN RETURN '{"error":"conflict","status":409}'::jsonb;
END $f$;

-- Preserve the existing visibility, released-version, consent and document predicates exactly.
CREATE OR REPLACE FUNCTION research_private.partnership_workspace(s research_private.studies,p research_private.partnership_partners,kind_filter text DEFAULT NULL,status_filter text DEFAULT NULL,query_filter text DEFAULT NULL) RETURNS jsonb LANGUAGE sql VOLATILE SET search_path='' AS $f$
 WITH visible AS (SELECT r.*,v.data,v.id AS visible_version_id,v.number AS visible_number,v.created_at AS visible_created_at,(r.partner_id=p.id AND (pg_catalog.current_setting('research.owner',true)='true' OR r.kind<>'analysis_result')) AS private_view FROM research_private.partnership_records r JOIN research_private.partnership_versions v ON v.id=CASE WHEN r.partner_id=p.id AND (pg_catalog.current_setting('research.owner',true)='true' OR r.kind<>'analysis_result') THEN r.head_version_id ELSE r.published_version_id END WHERE r.study_id=s.id AND (r.partner_id=p.id AND (pg_catalog.current_setting('research.owner',true)='true' OR r.kind<>'analysis_result') OR pg_catalog.current_setting('research.owner',true)<>'true' AND research_private.partnership_released(r,p.id)) AND research_private.partnership_version_current(v) AND (kind_filter IS NULL OR r.kind=kind_filter) AND (status_filter IS NULL OR r.status=status_filter) AND (query_filter IS NULL OR pg_catalog.strpos(pg_catalog.lower(v.data->>'title'),pg_catalog.lower(query_filter))>0))
 SELECT pg_catalog.jsonb_build_object('studyId',s.id,'partnerId',p.id,'studyTitle',s.config->>'title','study',pg_catalog.jsonb_build_object('id',s.id,'status',s.status,'revision',s.revision,'config',s.config),'grantedPermissions',COALESCE((SELECT pg_catalog.to_jsonb(m.permissions) FROM research_private.memberships m WHERE m.study_id=s.id AND m.actor_ref=p.actor_ref),'[]'::jsonb),'partnerName',p.profile->>'fullName','partnershipActive',research_private.partnership_live_member(s.id,p.actor_ref) AND s.status='active' AND s.config#>>'{approvals,status}'='approved' AND EXISTS(SELECT 1 FROM research_private.form_publications fp WHERE fp.study_id=s.id AND fp.version_id=(s.config->>'consentVersionId')::uuid) AND EXISTS(SELECT 1 FROM research_private.partnership_records ar JOIN research_private.partnership_executions ex ON ex.version_id=ar.head_version_id WHERE ar.study_id=s.id AND ar.partner_id=p.id AND ar.status='executed'),'recordCounts',COALESCE((SELECT pg_catalog.jsonb_object_agg(kind,n) FROM (SELECT kind,pg_catalog.count(*) n FROM visible GROUP BY kind) x),'{}'),'pendingCount',(SELECT pg_catalog.count(*) FROM visible WHERE status IN ('submitted','under_review','owner_review')),'deadlines',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('recordId',id,'date',COALESCE(data->>'dueDate',data->>'endDate',data->>'terminationDate'))) FROM visible WHERE COALESCE(data->>'dueDate',data->>'endDate',data->>'terminationDate') IS NOT NULL),'[]'),'records',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',id,'partnerId',partner_id,'kind',kind,'status',CASE WHEN private_view THEN status WHEN kind='contribution' AND status='completed' THEN 'completed' WHEN kind='contribution' THEN 'approved' ELSE 'published' END,'revision',CASE WHEN private_view THEN revision ELSE visible_number END,'title',data->>'title','updatedAt',CASE WHEN private_view THEN updated_at ELSE visible_created_at END,'headVersionId',visible_version_id) ORDER BY updated_at DESC,id) FROM visible),'[]'),'documents',COALESCE((SELECT pg_catalog.jsonb_agg(research_private.partnership_document(d)) FROM research_private.partnership_documents d WHERE d.study_id=s.id AND d.partner_id=p.id AND research_private.partnership_document_current(d) AND (pg_catalog.current_setting('research.owner',true)='true' OR NOT EXISTS(SELECT 1 FROM research_private.partnership_records ar JOIN research_private.partnership_versions av ON av.id=ar.head_version_id WHERE ar.study_id=s.id AND ar.partner_id=p.id AND ar.kind='analysis_result' AND (ar.id=d.record_id OR COALESCE(av.data->'resultDocumentIds','[]') ? d.id::text) AND NOT EXISTS(SELECT 1 FROM visible vis WHERE vis.id=ar.id AND COALESCE(vis.data->'resultDocumentIds','[]') ? d.id::text)))),'[]'),'snapshots',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',snap.id,'createdAt',snap.created_at,'consentProtocolVersionId',snap.consent_version_id,'questionnaireVersionIds',snap.questionnaire_version_ids)) FROM research_private.partnership_snapshots snap WHERE snap.study_id=s.id AND snap.partner_id=p.id AND research_private.partnership_snapshot_current(s.id,p.id,snap.id)),'[]')) $f$;
GRANT CREATE ON SCHEMA research_private TO research_worker;
ALTER FUNCTION research_private.intake_dispatch(text,text,jsonb) OWNER TO research_worker;
REVOKE CREATE ON SCHEMA research_private FROM research_worker;
CREATE FUNCTION public.research_intake_rpc(p_token text,p_action text,p_payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $f$ DECLARE result jsonb; BEGIN
 result:=research_private.intake_dispatch(p_token,p_action,p_payload);PERFORM research_private.intake_reset();RETURN result;
END $f$;
REVOKE ALL ON FUNCTION public.research_intake_rpc(text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.research_intake_rpc(text,text,jsonb) TO service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA research_private FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA research_private TO research_worker;
GRANT EXECUTE ON FUNCTION research_private.dispatch(text,text,jsonb),research_private.partnership_dispatch(text,text,jsonb),research_private.intake_dispatch(text,text,jsonb),research_private.intake_reset() TO service_role;
COMMIT;
